/// <summary>
/// Extension of the class <c>TAMRebateCreateTrans</c>
/// </summary>
[ExtensionOf(classStr(TAMRebateCreateTrans))]
final class METTAMRebateCreateTrans_Extension
{
    private RefRecId metDealId;

}

Method.Source:
/// <summary>
/// Extended this method to consider the 'External sell data' records for the 'Rebate deal transactions'.
/// </summary>
/// <param name = "_rebateTable">TAMRebateTable record id</param>
protected void processRebateTable(TAMRebateTable _rebateTable)
{
    next processRebateTable(_rebateTable);

    METProcMetrics procMetrics = METProcMetricsScope::current();
    if (procMetrics)
    {
        procMetrics.incProcessedCountWithDocument(_rebateTable.RebateId);
    }

    if (metDealId != _rebateTable.RebateDeal)
    {
        metDealId = _rebateTable.RebateDeal;
        this.processVolumetricTierTrans(metDealId);
    }
}

/// <summary>
/// Extended this method to consider the 'External sell data' records for the 'Rebate deal transactions'.
/// </summary>
/// <param name = "_dealRecId">TAMRebateDeal table record id</param>
protected void processVolumetricTierTrans(TAMRebateDealRecId _dealRecId)
{
    TAMRebateDeal           rebateDeal  = TAMRebateDeal::find(_dealRecId);

    // Run the MET tier rate calculation service job if the rebate deal is marked as a MET volumetric tier deal
    // 281410 - CB201- For Volumetric rebate Calculate tier rate rebate is not working properly if we click on Process provision without doing the Calculate tier rate rebate
    if (rebateDeal.METVolumetricTierDeal)
    {
        METTierRateTrans mETTierRateTrans;

        // Delete existing tier rate transactions for the same date range and rebate deal to avoid duplicates
        delete_from mETTierRateTrans
            where mETTierRateTrans.TAMRebateDealId == rebateDeal.Deal
            && mETTierRateTrans.FromDate == fromDate
            && mETTierRateTrans.ToDate == toDate;

        METTierRateCalculationContract contract = new METTierRateCalculationContract();
        METTierRateCalculationService  service  = new METTierRateCalculationService();

        // Set required contract parameters
        contract.parmFromDate(fromDate);
        contract.parmToDate(toDate);
        contract.parmRebateDealRecId(rebateDeal.Deal);

        // Run the service
        service.process(contract);
    }
}

/// <summary>
/// Bug 340352: [MS] E2E - RE-0031 Vendor Rebate - Batch Job Failed for Posting. MS SR# - 2603010030001346
/// </summary>
/// <param name = "_contract"><c>TAMRebateCreateTransContract</c></param>
public static void processRebateTrans(TAMRebateCreateTransContract _contract)
{
    // If auto date population is selected, populate from date with today -7 days and to date with today
    if (_contract.metParmAutoSetDate())
    {
        utcdatetime utcNowTimeZoneOffset = DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::utcNow(), DateTimeUtil::getUserPreferredTimeZone());
        ToDate endWeekDate = DateTimeUtil::date(utcNowTimeZoneOffset);
        FromDate startWeekDate = DateTimeUtil::date(DateTimeUtil::addDays(utcNowTimeZoneOffset, -6));

        _contract.parmFromDate(startWeekDate);
        _contract.parmToDate(endWeekDate);
    }

    next processRebateTrans(_contract);
}
